{
  "title": "CSCI-532: Introduction to Intelligent Security Systems",
  "learningObjectives": [
    "Define the core components of intelligent security systems and their role in information assurance.",
    "Explain how artificial intelligence methodologies enhance intrusion detection and monitoring capabilities.",
    "Evaluate the design principles of firewall structures and access control mechanisms using intelligent frameworks."
  ],
  "beats": [
    {
      "title": "Course Foundations and Scope",
      "claim": "CSCI-532 introduces intelligent methodologies for computer security and information assurance systems design.",
      "example": "Students will explore how AI-driven tools replace traditional rule-based security checks with adaptive threat recognition.",
      "visualDirection": "Display a slide titled 'Course Scope' with bullet points listing intelligent methodologies, information assurance, and systems design. Use a clean, academic font and a subtle security-themed background graphic.",
      "sourceIds": ["rit-csci-532"]
    },
    {
      "title": "Prerequisites and Course Constraints",
      "claim": "Students must have completed CSCI-331 or CSCI-351 and cannot have credit for CSCI-735 to enroll.",
      "example": "An enrollment portal would block registration if a student's transcript shows CSCI-735 credit, ensuring prerequisite alignment.",
      "visualDirection": "Show a checklist graphic with three items: 'CSCI-331/CSCI-351 Completed', 'CSCI-735 Credit Absent', and 'Prerequisites Met'. Use checkmarks and clear icons for each item.",
      "sourceIds": ["rit-csci-532"]
    },
    {
      "title": "Intelligent Methodologies in Security",
      "claim": "Intelligent methodologies apply adaptive algorithms to enhance security system performance and decision-making.",
      "example": "Machine learning models analyze network traffic patterns to identify anomalies that static rules might miss.",
      "visualDirection": "Illustrate a flowchart showing 'Raw Data' -> 'AI Analysis' -> 'Threat Assessment' -> 'Automated Response'. Use arrows and labeled nodes for clarity.",
      "sourceIds": ["rit-csci-532"]
    },
    {
      "title": "Intrusion Detection and Monitoring",
      "claim": "Intrusion detection and monitoring systems use intelligent analysis to identify unauthorized access attempts.",
      "example": "An AI-powered IDS tracks behavioral deviations in user activity and flags suspicious actions for investigation.",
      "visualDirection": "Present a dashboard mockup with metrics like 'False Positive Rate', 'Detection Accuracy', and 'Response Time'. Use color-coded indicators for status.",
      "sourceIds": ["rit-csci-532"]
    },
    {
      "title": "Access Control and Biological Authentication",
      "claim": "Access control mechanisms and biological authentication enhance security by verifying user identity through multiple factors.",
      "example": "Fingerprint and facial recognition systems integrate with traditional passwords to create multi-factor authentication protocols.",
      "visualDirection": "Draw a diagram comparing traditional access control (keycard/password) with intelligent access control (biometric + AI verification). Use side-by-side layout.",
      "sourceIds": ["rit-csci-532"]
    },
    {
      "title": "Firewall Structure and Design",
      "claim": "Firewall structures and design principles protect networks by filtering traffic based on intelligent policies.",
      "example": "Next-generation firewalls use AI to dynamically adjust rules based on real-time threat intelligence feeds.",
      "visualDirection": "Show a layered network diagram with a firewall layer highlighted, showing inbound/outbound traffic paths and AI decision points.",
      "sourceIds": ["rit-csci-532"]
    },
    {
      "title": "Course Project Implementation",
      "claim": "Students must implement a course project designing a security tool with an artificial intelligence methodology.",
      "example": "A team builds an AI-driven vulnerability scanner that prioritizes patches based on risk scoring algorithms.",
      "visualDirection": "Display a project roadmap timeline with phases: 'Requirement Gathering', 'AI Model Training', 'Tool Development', 'Testing'. Use milestone markers.",
      "sourceIds": ["rit-csci-532"]
    },
    {
      "title": "Performance Analysis Framework",
      "claim": "Students must undertake performance analysis to evaluate the effectiveness of their intelligent security tool.",
      "example": "Metrics like detection rate, latency, and resource utilization are measured to validate AI model accuracy.",
      "visualDirection": "Create a bar chart comparing 'Baseline Performance' vs. 'AI-Enhanced Performance' across three key metrics. Use contrasting colors for comparison.",
      "sourceIds": ["rit-csci-532"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "A practical analysis checklist ensures all intelligent security components are evaluated for robustness and compliance.",
      "example": "Instructors verify that the project includes threat modeling, AI validation, and documentation of system limitations.",
      "visualDirection": "List a checklist with items: 'Threat Model Documented', 'AI Model Validated', 'Performance Metrics Reported', 'Security Review Completed'. Use checkboxes for tracking.",
      "sourceIds": ["rit-csci-532"]
    },
    {
      "title": "Instructor Guidance and Syllabus Alignment",
      "claim": "This lesson provides foundational concepts and problem-solving methods aligned with the official catalog description.",
      "example": "Instructors use this structure to scaffold student understanding while maintaining flexibility for detailed syllabus coverage.",
      "visualDirection": "Show a split screen: left side 'Lesson Blueprint', right side 'Official Catalog Description'. Use connecting arrows to highlight alignment points.",
      "sourceIds": ["rit-csci-532"]
    }
  ]
}
